mapper.select:
select distinct tracking_id,estimated_delivery ,event_status_code,event_status_description ,event_location_city ,event_date_time, shipped_ts,actual_delivered_ts ,origin_scan_ts ,out_for_delivery_ts , is_active from edw.fact_ups_shipment_tracking_v4 where shipped_ts > '2024-04-01'
and is_active = 1
and tracking_id in
#{id}
order by tracking_id,event_date_time ;

select distinct tracking_id, is_active ,statusdetail_description ,statusdetail_ts , service_type ,created_ts ,events_description ,event_ts , status_city ,shipment_delay_city ,shipment_exception ,exception_description , return_tracking_number_new from edw.fact_fedex_shipment_tracking_v4 where created_ts >'2024-01-01'
and is_active = 1
and tracking_id in
#{id}
order by tracking_id,event_ts ;

select foli.po_id ,fulfillment_delivery_do_id as do_id ,foli.shipped_sku,foli.shipping_amt,shipped_qty ,foli.physical_fulfiller_id ,UPPER(tracking_id) as tracking , current_promise_delivery_ts::Date as EDD, fgo.entry_ts as order_entry_date,fgo.updated_ts as ship_scan_date,foli.delivered_ts::Date,foli.fulfillment_carrier_id, foli.order_ts_est ,foli.sales_price,foli.list_price ,foli.line_item_status ,foli.order_status ,foli.cancellation_reason ,foli.cancellation_status
from edw.fact_order_line_items foli left join edw.fact_geodis_orders fgo on foli.fulfillment_delivery_do_id = fgo.fulfillment_po_id where foli.is_active =1 and fgo.is_active = 1
and foli.po_id in
#{id}
and foli.fulfillment_delivery_do_id in
#{id}
and foli.tracking_id in
#{id}
and physical_fulfiller_id = 'geodis' and product_type = 'physical'

select foli.po_id ,fulfillment_delivery_do_id as do_id ,foli.shipped_sku,foli.shipping_amt,foli.physical_fulfiller_id ,UPPER(tracking_id) as tracking , current_promise_delivery_ts::Date as EDD,foli.delivered_ts::Date,foli.fulfillment_carrier_id,foli.sales_price,foli.list_price
from edw.fact_order_line_items foli where foli.is_active =1
and foli.po_id in
#{id}
and foli.fulfillment_delivery_do_id in
#{id}
and foli.tracking_id in
#{id}
and product_type = 'physical'

select fr.po_id , frsl.so_id, forward_do_id as odo, do_id as rdo, sku, frsl.quantity, fr.refund_status , returns_channel , return_reason , return_tracking_id , return_status , return_shipped_ts , return_delivered_ts , return_shipped_ts, label_generated_ts, initiated_ts , return_sub_reason_code , return_address_id from edw.fact_returns_v4 fr join edw.fact_purchase_order_line_item fpol on fr.return_line_item_id = fpol.line_item_id join edw.fact_return_so_line_item frsl on fpol.return_request_id = frsl.return_request_id and fpol.model_code = frsl.sku where fr.is_active = 1 and frsl.is_active = 1 and fpol.is_active = 1
and fr.po_id in
#{id}
and frsl.do_id in
#{id}
